mapper.select:
SELECT DISTINCT s.store_id FROM service_item s WHERE s.status = 'ACTIVE'
AND s.category_id = #{categoryId}
ORDER BY s.store_id ASC

SELECT t.service_id, t.store_id, t.merchant_id, t.service_name, t.category_id, t.category_code, t.category_name, t.category_sort_no, t.sale_price, t.list_price, t.duration_minutes, t.fulfillment_type FROM ( SELECT s.id AS service_id, s.store_id, s.merchant_id, s.service_name, c.id AS category_id, c.category_code, c.category_name, c.sort_no AS category_sort_no, s.price AS sale_price, s.list_price, s.duration_minutes, s.fulfillment_type, ROW_NUMBER() OVER (PARTITION BY s.store_id ORDER BY s.id ASC) AS store_rank FROM service_item s LEFT JOIN service_category c ON c.id = s.category_id WHERE s.status = 'ACTIVE' AND s.store_id IN
#{storeId}
) t ORDER BY t.store_id ASC, t.service_id ASC
